/* Metadata de instanciación por nombre técnico de proceso — mismo patrón que
 * ProcesosPage.tsx/ProcesosPage.svelte: solo CreacionCuentaAhorros tiene tab
 * de destino (Perfil del Cliente); un proceso sin entrada aquí no muestra
 * botón de instanciar. */
const META = {
  CreacionCuentaAhorros: { tabName: "PerfilCliente" }
};

appsmith.onReady(() => {
  render(appsmith.model);
  if (typeof appsmith.onModelChange === "function") {
    appsmith.onModelChange((m) => render(m));
  }
});

function render(model) {
  const procesos = (model && model.procesos) || [];
  const grid = document.getElementById("procesos-grid");
  const empty = document.getElementById("procesos-empty");
  if (!grid || !empty) return;

  grid.innerHTML = "";

  if (procesos.length === 0) {
    empty.style.display = "block";
    return;
  }
  empty.style.display = "none";

  procesos.forEach((p) => {
    const meta = META[p.name];

    const card = document.createElement("div");
    card.className = "proc-card";

    const top = document.createElement("div");
    top.className = "proc-card__top";
    const version = document.createElement("span");
    version.className = "proc-card__version";
    version.textContent = "v" + p.version;
    top.appendChild(version);
    card.appendChild(top);

    const name = document.createElement("div");
    name.className = "proc-card__name";
    name.textContent = p.displayName || p.name;
    card.appendChild(name);

    const id = document.createElement("div");
    id.className = "proc-card__id";
    id.textContent = "ID: " + p.id;
    card.appendChild(id);

    const footer = document.createElement("div");
    footer.className = "proc-card__footer";
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "proc-card__btn";
    btn.textContent = "Instanciar";
    btn.disabled = !meta;
    if (meta) {
      btn.addEventListener("click", () => {
        appsmith.triggerEvent("onInstanciar", { tabName: meta.tabName });
      });
    }
    footer.appendChild(btn);
    card.appendChild(footer);

    grid.appendChild(card);
  });
}

